def fix_orientation(image_file):
  img = Image.open(image_file)
  orientation = img._getexif()[274]

  if orientation == 3:
    img = img.rotate(180)
  elif orientation == 6:
    img = img.rotate(270)
  elif orientation == 8:
    img = img.rotate(90)

