import yaml
from django.http import HttpResponse
from django.conf.urls import url

class Layout:
    def __init__(self, name, rooms):
        self.name = name
        self.rooms = rooms

def layout_to_yaml(layout):
    return yaml.dump(layout)

def layout_from_yaml(yaml_string):
    return yaml.load(yaml_string, Loader=yaml.FullLoader)  # Ensure to use FullLoader for security reasons

def get_layout(request, layout_id):
    layout = Layout.objects.get(id=layout_id)
    yaml_string = layout_to_yaml(layout)
    return HttpResponse(yaml_string)

def save_layout(request):
    yaml_string = request.POST["yaml"]
    layout = layout_from_yaml(yaml_string)
    layout.save()
    return HttpResponse("Layout saved!")

urlpatterns = [
    url(r'^get_layout/(?P<layout_id>\d+)$', get_layout),
    url(r'^save_layout$', save_layout),
]
```

